function (variables) {
	var g = new ReadOnlyDetailView(variables.element);
	g.title = function (data) { return "" + kendo.htmlEncode(Payment.types[data.RemittanceAdviceTypeId-1].name) + " #" + kendo.htmlEncode(data.Number) + " [resource_shortdisplayname[from]]: " + kendo.htmlEncode(data.DebtorName) + " [resource_shortdisplayname[to]] " + kendo.htmlEncode(data.CreditorName) + ""; };
	// optional, but we want a subset of fields here so lets be explicit.
	g.fields = [
		{ field: "Number", title: "[resource_shortdisplayname[PaymentReference]]", description: "[resource_description[PaymentReference]]" },
		{ field: "DebtorName", title: "[resource_shortdisplayname[DebtorName]]", description: "[resource_description[DebtorName]]" },
		{ field: "DebtorState", template: function (data) { return "" + kendo.htmlEncode(B2B.transactionStates[data.DebtorState]) + ""; }, title: "[resource_shortdisplayname[DebtorState]]", description: "[resource_description[DebtorState]]" },
		{ field: "SourceSystemId", title: "[resource_shortdisplayname[sourcesystemid]]", description: "[resource_description[sourcesystemid]]" },
		{ field: "CreditorName", title: "[resource_shortdisplayname[CreditorName]]", description: "[resource_description[CreditorName]]" },
		{ field: "CreditorState", template: function (data) { return "" + kendo.htmlEncode(B2B.transactionStates[data.CreditorState]) + ""; }, title: "[resource_shortdisplayname[CreditorState]]", description: "[resource_description[CreditorState]]" },
		{ field: "FunderState", template: function (data) { return "" + ((data.FunderState) ? B2B.transactionStates[data.FunderExternalState]: '') + ""; }, title: "[resource_shortdisplayname[FunderState]]", description: "[resource_description[FunderState]]" },
		{ field: "CreationDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[CreationDate]]", description: "[resource_description[CreationDate]]" },
		{ field: "ReceivedDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[ReceivedDate]]", description: "[resource_description[ReceivedDate]]" },
		{ field: "DebtorPaymentDate", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[BuyerPaymentDate]]", description: "[resource_description[BuyerPaymentDate]]" },
		{ field: "LastUpdated", type: "date", format: type.dateFormat, title: "[resource_shortdisplayname[LastUpdated]]", description: "[resource_description[LastUpdated]]" },
		{ field: "Value", type: "number", format: type.moneyFormat, title: "[resource_shortdisplayname[Value]]", description: "[resource_description[Value]]" },
		{ field: "Comment", type: "string",  title: "[resource_shortdisplayname[Comment]]", description: "[resource_description[Comment]]" }
	];
	g.splits = ["CreationDate"];
	g.toolbar = "<button onClick='javascript: history.go(-1)'><span class='k-icon k-i-arrow-parent'></span> [resource_shortdisplayname[back]]</button>";
	variables.PaymentDetails = g;
}
